// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.smsimport timber.log.Timberimport com.roshan.persona.connectivity.model.SmartReplySuggestionimport com.roshan.persona.connectivity.model.SmartReplySourceimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Smart Reply Engine v3 (Module 11 v3 — Step 11.4, Elite Feature). * * Generates 3 contextually appropriate SMS reply suggestions using local LLM. * v3 adds **Smart Payload** — context-aware replies that include device state. * * ## v3 Smart Payload (per strategy v3 §"Smart Payload Delivery") * * When auto-replying, NOUS doesn't send generic text — it leverages device context: * * ``` * Incoming SMS: "Where are you?" *   ↓ * SmartReplyEngine generates 3 options: *   1. "I'm driving. ETA 15 mins. (Sent by NOUS AI)"        ← Smart Payload (driving context) *   2. "On my way, will be there soon!"                      ← Standard reply *   3. "Running a bit late, apologies!"                      ← Polite variant * ``` * * ## How it works * * 1. **Scrub PII** from the incoming message (PiiScrubber). * 2. **Build context** — sender name, time of day, user activity, device state. * 3. **Call local LLM** — "Generate 3 short replies to this message." * 4. **Add Smart Payload** — if user is driving/meeting/sleeping, prepend context. * 5. **Return 3 suggestions** — user picks one (voice or tap). * * ## Privacy * *  - SMS content is scrubbed of PII before LLM sees it. *  - LLM runs **on-device only** (Module 4 local LLM). *  - No SMS content ever leaves the device. *  - If local LLM is unavailable, falls back to templates. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§SmartReplyEngine v3 + Smart Payload</a> */class SmartReplyEngine(    private val llm: SmartReplyLlm?,    private val contextProvider: () -> SmartReplyContext,    private val dispatcher: CoroutineDispatcher,) {    /**     * Generate 3 smart reply suggestions for [incomingMessage].     *     * @param incomingMessage the SMS message to reply to.     * @param senderName optional sender name (for personalization).     * @return 3 reply suggestions (or template fallbacks if LLM unavailable).     */    suspend fun generateReplies(        incomingMessage: String,        senderName: String? = null,    ): SmartReplySuggestion = withContext(dispatcher) {        Timber.tag(TAG).d("Generating smart replies for: ${incomingMessage.take(50)}...")        // 1. Get device context (driving, meeting, sleeping, etc.).        val context = contextProvider()        // 2. Try local LLM first.        if (llm != null && llm.isReady()) {            val llmReplies = tryLlmReplies(incomingMessage, senderName, context)            if (llmReplies.isNotEmpty()) {                val payload = buildPayload(context)                return@withContext SmartReplySuggestion(                    replies = llmReplies.take(3),                    source = if (payload != null) SmartReplySource.CONTEXTUAL else SmartReplySource.LOCAL_LLM,                    contextPayload = payload,                )            }        }        // 3. Fallback to templates.        Timber.tag(TAG).d("LLM unavailable or failed — using template replies.")        val templateReplies = generateTemplateReplies(incomingMessage, context)        SmartReplySuggestion(            replies = templateReplies,            source = SmartReplySource.TEMPLATE,            contextPayload = buildPayload(context),        )    }    /**     * Build a Smart Payload string from device context.     *     * Example: "Roshan is driving. ETA 15 mins." (prepended to the reply).     */    internal fun buildPayload(context: SmartReplyContext): String? {        val parts = mutableListOf<String>()        if (context.isDriving) {            parts.add("I'm driving")            context.etaMinutes?.let { parts.add("ETA ${it}m") }        } else if (context.isInMeeting) {            parts.add("I'm in a meeting")            context.meetingEndsAt?.let { parts.add("until $it")                parts.removeAt(parts.size - 2) // replace "I'm in a meeting" with "I'm in a meeting until X"            }        } else if (context.isSleeping) {            parts.add("I'm asleep")        } else if (context.isAtGym) {            parts.add("I'm at the gym")        }        if (parts.isEmpty()) return null        return parts.joinToString(". ") + ". (Sent by NOUS AI)"    }    /**     * Try generating replies via local LLM.     *     * Scrubs PII, builds prompt, calls LLM, parses 3 replies.     */    private suspend fun tryLlmReplies(        incomingMessage: String,        senderName: String?,        context: SmartReplyContext,    ): List<String> {        // Scrub PII from incoming message.        val scrubbed = PiiScrubber.scrub(incomingMessage)        val senderLine = senderName?.let { "From: $it" } ?: ""        val contextLine = buildPayload(context)?.let { "Context: $it" } ?: ""        val prompt = """Generate 3 short SMS replies (max 15 words each) for the following message.Be natural, casual, and helpful. One reply per line, no numbering.$senderLineMessage: "$scrubbed"$contextLineReply 1:Reply 2:Reply 3:        """.trimIndent()        val response = try {            val gen = llm ?: return emptyList()            gen.generate(prompt)        } catch (t: Throwable) {            Timber.tag(TAG).w("LLM generation failed", t)            return emptyList()        }        return parseLlmReplies(response)    }    /**     * Parse LLM response into 3 reply strings.     *     * Expected format: one reply per line.     */    internal fun parseLlmReplies(response: String): List<String> {        return response.lines()            .map { it.trim() }            .filter { it.isNotBlank() && !it.startsWith("Reply") && !it.startsWith("#") }            .take(3)    }    /**     * Generate template-based replies (fallback when LLM unavailable).     *     * Uses keyword matching on the incoming message.     */    internal fun generateTemplateReplies(        incomingMessage: String,        context: SmartReplyContext,    ): List<String> {        val lower = incomingMessage.lowercase()        val payload = buildPayload(context)        val baseReplies = when {            // Questions about location.            lower.contains("where are you") || lower.contains("where r u") -> listOf(                "On my way!",                "Almost there.",                "Running a bit late, sorry!",            )            // Questions about timing.            lower.contains("when") && (lower.contains("come") || lower.contains("reach") || lower.contains("arrive")) -> listOf(                "I'll be there soon!",                "Running 10 mins late.",                "On the way now.",            )            // Yes/no questions.            lower.contains("?") -> listOf(                "Yes!",                "Let me check and get back to you.",                "Not sure, give me a moment.",            )            // Greetings.            lower.contains("hi") || lower.contains("hello") || lower.contains("hey") -> listOf(                "Hey! What's up?",                "Hi! How are you?",                "Hello! How can I help?",            )            // Default.            else -> listOf(                "Got it, thanks!",                "I'll get back to you soon.",                "Understood, talk later!",            )        }        // If Smart Payload is available, prepend it to the first reply.        return if (payload != null) {            listOf(payload) + baseReplies.take(2)        } else {            baseReplies        }    }    private companion object {        private const val TAG = "SmartReplyEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** * Device context for Smart Payload generation. * * @param isDriving user is currently driving. * @param isInMeeting user is in a calendar meeting. * @param isSleeping user is likely sleeping (late night + device face down). * @param isAtGym user is at the gym (location-based). * @param etaMinutes estimated time of arrival (if driving). * @param meetingEndsAt when the meeting ends (e.g., "3 PM"). */data class SmartReplyContext(    val isDriving: Boolean = false,    val isInMeeting: Boolean = false,    val isSleeping: Boolean = false,    val isAtGym: Boolean = false,    val etaMinutes: Int? = null,    val meetingEndsAt: String? = null,)/** * LLM interface for smart reply generation. * * Real implementation wires to Module 4 (LocalLlmProvider). * Tests inject a fake. */interface SmartReplyLlm {    /** Generate text from [prompt]. */    suspend fun generate(prompt: String): String    /** True if the local LLM is loaded and ready. */    fun isReady(): Boolean}